    N = int(input())
    vertices = [tuple(map(int, input().split())) for _ in range(N)]

    def area(a, b, c):
        return abs(a[0]*(b[1]-c[1]) + b[0]*(c[1]-a[1]) + c[0]*(a[1]-b[1])) / 2

    total_area = area(vertices[0], vertices[-1], vertices[1])
    for i in range(2, N):
        total_area += area(vertices[0], vertices[i-1], vertices[i])

    def find_intersection(x1, y1, x2, y2, x3, y3, x4, y4):
        det = (x1-x2)*(y3-y4) - (y1-y2)*(x3-x4)
        if det == 0:
            return None
        t = ((x1-x3)*(y3-y4) - (y1-y3)*(x3-x4)) / det
        x = x1 + t*(x2-x1)
        y = y1 + t*(y2-y1)
        return x, y

    intersections = []
    for i in range(N):
        for j in range(i+1, N):
            x1, y1 = vertices[i]
            x2, y2 = vertices[(i+1) % N]
            x3, y3 = vertices[j]
            x4, y4 = vertices[(j+1) % N]
            inter = find_intersection(x1, y1, x2, y2, x3, y3, x4, y4)
            if inter:
                intersections.append(inter)

    intersections = sorted(set(intersections), key=lambda x: x[0])
