                    ((d[0] - c[0]) / (d[1] - c[1]) - (b[0] - a[0]) / (b[1] - a[1]))
                if min(a[0], b[0]) <= x <= max(a[0], b[0]) and \
                   min(c[0], d[0]) <= x <= max(c[0], d[0]):
